import type { LooseKeys } from '@mantine/form';
import { randomId } from '@mantine/hooks';
import type { JobApplicationValues, Position, WorkArrangement } from './types';

export const STEPS = ['Personal', 'Experience', 'Availability', 'Review'] as const;

export const REVIEW_STEP = STEPS.length - 1;

export const NOTES_MAX_LENGTH = 500;

export const WORK_ARRANGEMENTS: { value: WorkArrangement; label: string }[] = [
  { value: 'remote', label: 'Remote' },
  { value: 'hybrid', label: 'Hybrid' },
  { value: 'on-site', label: 'On-site' },
];

export function createPosition(): Position {
  return { id: randomId(), company: '', title: '', years: [null, null] };
}

export function getInitialValues(): JobApplicationValues {
  return {
    firstName: '',
    lastName: '',
    email: '',
    phone: '',
    phoneDisplay: '',
    linkedin: '',
    currentTitle: '',
    yearsOfExperience: '',
    positions: [createPosition()],
    startDate: null,
    salary: '',
    workArrangement: '',
    notes: '',
  };
}

// Paths in the order they appear on screen, so the first invalid one is the first to focus
export function getStepPaths(
  step: number,
  values: JobApplicationValues
): LooseKeys<JobApplicationValues>[] {
  switch (step) {
    case 0:
      return ['firstName', 'lastName', 'email', 'phone', 'linkedin'];
    case 1:
      return [
        'currentTitle',
        'yearsOfExperience',
        'positions',
        ...values.positions.flatMap((_, index) => [
          `positions.${index}.company`,
          `positions.${index}.title`,
          `positions.${index}.years`,
        ]),
      ];
    case 2:
      return ['startDate', 'salary', 'workArrangement', 'notes'];
    default:
      return [];
  }
}

import { Group, NumberInput, Radio, SimpleGrid, Stack, Text, Textarea } from '@mantine/core';
import { DatePickerInput } from '@mantine/dates';
import { NOTES_MAX_LENGTH, WORK_ARRANGEMENTS } from '../constants';
import type { JobApplicationFormType } from '../types';

export function AvailabilityStep({ form }: { form: JobApplicationFormType }) {
  const notes = form.useWatchValue('notes');

  return (
    <Stack gap="md" mt="xl">
      <SimpleGrid cols={{ base: 1, sm: 2 }}>
        <DatePickerInput
          label="Earliest start date"
          placeholder="Pick a date"
          withAsterisk
          minDate={new Date()}
          valueFormat="MMMM D, YYYY"
          {...form.getInputProps('startDate')}
        />
        <NumberInput
          label="Expected salary"
          placeholder="Annual salary in USD"
          prefix="$"
          thousandSeparator=","
          allowNegative={false}
          allowDecimal={false}
          hideControls
          {...form.getInputProps('salary')}
        />
      </SimpleGrid>
      <Radio.Group label="Work arrangement" withAsterisk {...form.getInputProps('workArrangement')}>
        <Group mt="xs">
          {WORK_ARRANGEMENTS.map((option) => (
            <Radio key={option.value} value={option.value} label={option.label} />
          ))}
        </Group>
      </Radio.Group>
      <Textarea
        label="Notes"
        placeholder="Anything else we should know"
        autosize
        minRows={3}
        maxRows={8}
        maxLength={NOTES_MAX_LENGTH}
        bottomSection={
          <Text size="xs" ta="right" c={notes.length >= NOTES_MAX_LENGTH ? 'red' : undefined}>
            {notes.length}/{NOTES_MAX_LENGTH}
          </Text>
        }
        {...form.getInputProps('notes')}
      />
    </Stack>
  );
}

import type { RefObject } from 'react';
import { IconPlus } from '@tabler/icons-react';
import {
  Button,
  Group,
  Input,
  NumberInput,
  SimpleGrid,
  Stack,
  Text,
  TextInput,
} from '@mantine/core';
import { createPosition } from '../constants';
import type { JobApplicationFormType } from '../types';
import { PositionFields } from './PositionFields';

interface ExperienceStepProps {
  form: JobApplicationFormType;
  addPositionRef: RefObject<HTMLButtonElement | null>;
}

export function ExperienceStep({ form, addPositionRef }: ExperienceStepProps) {
  const positions = form.useWatchValue('positions');

  return (
    <Stack gap="md" mt="xl">
      <SimpleGrid cols={{ base: 1, sm: 2 }}>
        <TextInput
          label="Current title"
          placeholder="Current title"
          withAsterisk
          {...form.getInputProps('currentTitle')}
        />
        <NumberInput
          label="Years of experience"
          placeholder="Years of experience"
          withAsterisk
          min={0}
          max={50}
          clampBehavior="strict"
          allowNegative={false}
          allowDecimal={false}
          {...form.getInputProps('yearsOfExperience')}
        />
      </SimpleGrid>

      <Stack gap="xs">
        <Input.Label required>Previous positions</Input.Label>
        {positions.length > 0 ? (
          positions.map((position, index) => (
            <PositionFields key={position.id} form={form} index={index} />
          ))
        ) : (
          <Text size="sm">No positions added</Text>
        )}
        {form.errors.positions && <Input.Error>{form.errors.positions}</Input.Error>}
        <Group>
          <Button
            ref={addPositionRef}
            variant="default"
